using MediatR;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Exceptions;
namespace JTradeERP.Application.Features.MasterData.Suppliers.UpdateSupplier;
public sealed class UpdateSupplierHandler(IApplicationDbContext db):IRequestHandler<UpdateSupplierCommand,UpdateSupplierResponse>{public async Task<UpdateSupplierResponse> Handle(UpdateSupplierCommand r,CancellationToken ct){var e=db.Suppliers.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Supplier not found.");if(db.Suppliers.Any(x=>x.Id!=r.Id&&x.SupplierCode==r.SupplierCode.Trim()))throw new ConflictException("Supplier code already exists.");e.Update(r.SupplierCode,r.Name,r.Address,r.ContactInformation,r.PaymentTerms,r.TRN);await db.SaveChangesAsync(ct);return new(e.Id,e.SupplierCode,e.Name,e.Address,e.ContactInformation,e.PaymentTerms,e.TRN);}}
